const fs = require("fs");
const file = "C:/Users/USER/Downloads/agent-test/vibe/runs/sudoku_haiku-5-5_r1/work/index.html";
const html = fs.readFileSync(file, "utf8");
const js = html.split("<script>")[1].split("</script>")[0];

const stub = () => ({
  classList: { add() {}, remove() {}, toggle() {} },
  addEventListener() {}, setAttribute() {}, focus() {}, select() {}, appendChild() {},
});
const document = { getElementById: stub, createElement: stub };

const api = new Function("document",
  js + "\n;return { generatePuzzle, countSolutions };")(document);

function validGrid(g) {
  const ok = (cellsOf) => {
    const s = new Set();
    for (let k = 0; k < 9; k++) s.add(g[cellsOf(k)]);
    return s.size === 9;
  };
  for (let r = 0; r < 9; r++) if (!ok((k) => r * 9 + k)) return false;
  for (let c = 0; c < 9; c++) if (!ok((k) => k * 9 + c)) return false;
  for (let b = 0; b < 9; b++) {
    const br = Math.floor(b / 3) * 3, bc = (b % 3) * 3;
    if (!ok((k) => (br + Math.floor(k / 3)) * 9 + bc + (k % 3))) return false;
  }
  return true;
}

let worst = 0;
const clues = [];
for (let t = 0; t < 30; t++) {
  const t0 = Date.now();
  const { puzzle, solution } = api.generatePuzzle();
  worst = Math.max(worst, Date.now() - t0);
  if (!validGrid(solution)) throw new Error("invalid solution grid");
  if (api.countSolutions(puzzle.slice(), 2) !== 1) throw new Error("puzzle not unique");
  for (let i = 0; i < 81; i++) {
    if (puzzle[i] && puzzle[i] !== solution[i]) throw new Error("clue mismatch");
  }
  clues.push(puzzle.filter((x) => x).length);
}
console.log("30 puzzles OK. Max generation ms:", worst,
  "Clue count min/max:", Math.min(...clues), Math.max(...clues));

